 const atlas=()=>atlasPromise||(atlasPromise=fetch('/assets/atlas.json').then(r=>r.json()).then(a=>a.topics));
 const normal=s=>String(s).toLowerCase().replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();
 function findTopics(topics,q){const n=normal(q);if(!n)return topics;return topics.map(t=>{const title=normal(t.title),aliases=(t.aliases||[]).map(normal);return [t,title===n||aliases.includes(n)?10:title.includes(n)?6:aliases.some(a=>a.includes(n))?4:n.includes(title)&&title.length>3?3:0];}).filter(x=>x[1]).sort((a,b)=>b[1]-a[1]).map(x=>x[0]);}
 const safeSource=t=>/^https:\/\/medlineplus\.gov\//.test(t.url)?'<a target="_blank" rel="noopener noreferrer" href="'+esc(t.url)+'">Read on MedlinePlus ↗</a>':'';
