   q.oninput=()=>{limit=35;show();};list.onclick=e=>{const id=e.target.closest('[data-topic]')?.dataset.topic;if(!id)return;const t=topics.find(x=>String(x.id)===id);if(t){document.querySelector('#topic').innerHTML=topicCard(t);document.querySelector('#topic').scrollIntoView({behavior:'smooth'});}};show();
