   form.onsubmit=async e=>{e.preventDefault();const question=form.elements.q.value.trim();if(!question)return;const b=form.querySelector('button');b.disabled=true;out.innerHTML='<p>Finding information…</p>';try{let answer;if(source.value==='online'){if(!form.elements.consent.checked)throw Error('Please confirm consent before sending a question.');answer=(await MPCloud.assistant(question)).answer;out.innerHTML='<div class="empty article">'+esc(answer)+'</div>';}else {const topics=await atlas(),t=findTopics(topics,question)[0];if(!t){out.innerHTML=empty('No matching health topic','Try just the medical term in the offline guide.');return;}answer=t.summary;out.innerHTML=topicCard(t);}const saveButton=document.createElement('button');saveButton.className='btn';saveButton.textContent='Save answer';saveButton.onclick=async()=>{saveButton.disabled=true;try{await save('assistant','Educational answer',{answer:answer.slice(0,7000)});saveButton.textContent='Saved';}catch(err){notify(err.message);saveButton.disabled=false;}};out.append(saveButton);}catch(err){out.innerHTML=note(err.message,true);}finally{b.disabled=false;}};
