 function reports(){
   page().innerHTML=hero('reports','Explore imaging & reports','Read your report text and inspect local images without uploading them.')+note('This version extracts candidate text values only. Experimental image classifiers and scanned-PDF OCR are not bundled; image viewing is not diagnostic.',true)+'<div class="grid two"><article class="card tile indigo"><h3>Report reading</h3><label class="field">Open a text report or PDF<input type="file" accept=".txt,.pdf,text/plain,application/pdf" id="report-file"></label><label class="field">Or paste report text<textarea id="report-text" maxlength="60000" placeholder="Paste report text (remove personal identifiers)"></textarea></label><button class="btn primary" id="read-report">Find candidate lab values</button><div id="report-results"></div></article><article class="card tile blue"><h3>Local image viewer</h3><p>Inspect JPEG or PNG images locally. No classification or diagnosis is provided.</p><input class="input" type="file" id="image-file" accept="image/png,image/jpeg,image/webp"><div id="image-view"></div></article></div>';
   document.querySelector('#report-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024){notify('File is too large (10 MB limit).');return;}try{let text;if(f.type==='application/pdf'||f.name.toLowerCase().endsWith('.pdf')){const pdf=await import('/vendor/pdf.min.mjs');pdf.GlobalWorkerOptions.workerSrc='/vendor/pdf.worker.min.mjs';const doc=await pdf.getDocument({data:new Uint8Array(await f.arrayBuffer()),isEvalSupported:false,useSystemFonts:true}).promise;text='';for(let i=1;i<=Math.min(10,doc.numPages);i++){const p=await doc.getPage(i);const c=await p.getTextContent();text+=c.items.map(x=>x.str+(x.hasEOL?'\n':' ')).join('')+'\n';}await doc.destroy();}else text=await f.text();document.querySelector('#report-text').value=text.slice(0,60000);notify(text.trim()?'Report text loaded. Verify all values.':'No readable text found. Scanned PDF OCR is not available.');}catch{notify('Could not read this file. Try pasting report text.');}};
   document.querySelector('#read-report').onclick=()=>{const text=document.querySelector('#report-text').value, data={};for(const [k,re] of Object.entries(reportPatterns)){const m=text.match(re);if(m)data[k]=m[1];}const out=document.querySelector('#report-results');out.innerHTML=Object.keys(data).length?note('Verify every candidate value and its units against the original report.')+Object.entries(data).map(([k,v])=>'<div class="list-item"><b>'+esc(k)+'</b>'+esc(v)+'</div>').join('')+'<button class="btn" id="save-report">Save candidate values only</button>':empty('No candidate values found','Try pasting a text report.');const b=document.querySelector('#save-report');if(b)b.onclick=async()=>{b.disabled=true;try{await save('report','Report reading',data);b.textContent='Saved';}catch(err){notify(err.message);b.disabled=false;}};};
   document.querySelector('#image-file').onchange=e=>{const f=e.target.files[0];if(!f||!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>15*1024*1024){notify('Choose a PNG, JPEG or WebP image under 15 MB.');return;}const out=document.querySelector('#image-view');out.textContent='';const img=document.createElement('img');img.className='report-image';img.alt='Selected local image';img.src=URL.createObjectURL(f);img.onload=()=>URL.revokeObjectURL(img.src);out.append(img);const b=document.createElement('button');b.className='btn';b.textContent='Save viewing record (no image)';b.onclick=async()=>{b.disabled=true;try{await save('imaging','Image viewed',{type:f.type,details:'Local viewing only — no model inference'});b.textContent='Saved';}catch(err){notify(err.message);b.disabled=false;}};out.append(b);};
 }
 const letters='abcdefghijklmnopqrstuvwxyz',dots='⠁⠃⠉⠙⠑⠋⠛⠓⠊⠚⠅⠇⠍⠝⠕⠏⠟⠗⠎⠞⠥⠧⠺⠭⠽⠵',brailleMap=Object.assign(Object.fromEntries([...letters].map((x,i)=>[x,dots[i]])),{' ':' ', ',':'⠂','.':'⠲','?':'⠦','!':'⠖',';':'⠆',':':'⠒',"'":'⠄','-':'⠤'});
 function convert(text,reverse){let cap=false,num=false,res='';const digits='1234567890', inv=Object.fromEntries(Object.entries(brailleMap).map(([k,v])=>[v,k]));for(const ch of text){if(!reverse){if(digits.includes(ch)){if(!num)res+='⠼';res+=dots[digits.indexOf(ch)];num=true;}else{num=false;res+=brailleMap[ch]??(brailleMap[ch.toLowerCase()]?'⠠'+brailleMap[ch.toLowerCase()]:'�');}}else{if(ch==='⠠'){cap=true;continue;}if(ch==='⠼'){num=true;continue;}const i=dots.indexOf(ch);if(num&&i>=0&&i<10){res+=digits[i];continue;}num=false;const c=inv[ch]??'?';res+=cap?c.toUpperCase():c;cap=false;}}return res;}
